-- Check WV senate
SELECT state_code, status, called_winner, primary_winner FROM senate_races WHERE state_code = 'WV';
-- Also check for any senate races where called_winner is set but status is not Called/Certified (data inconsistency)
SELECT state_code, status, called_winner, primary_winner FROM senate_races WHERE called_winner IS NOT NULL AND status NOT IN ('Called','Certified');

